#ifdef GL_ES
precision highp float;
precision mediump int;
#endif

uniform sampler2D SpriteTextureSampler;
uniform vec4 Settings[1];
#define Radius Settings[0].x
#define Softness Settings[0].y
varying vec4 vFrontColor;
varying vec4 vTexCoord0;









struct VS_OUT
{
    vec4 Position;
    vec4 Color;
    vec2 TextureCoordinates;
};

vec4 MainPS(VS_OUT _input)
{
    vec4 c = texture2D(SpriteTextureSampler, _input.TextureCoordinates);
    vec2 centered = _input.TextureCoordinates - vec2(0.5, 0.5);
    float d = length(centered);
    float vig = smoothstep(Radius + Softness, Radius - Softness, d);
    return vec4(c.rgb * vig, c.a) * _input.Color;
}








void main() {
    VS_OUT _input;
    _input.Position = gl_FragCoord;
    _input.Color = vFrontColor;
    _input.TextureCoordinates = vTexCoord0.xy;
    gl_FragColor = MainPS(_input);
}

